export type KnowledgeSpecialistMode = "automatic" | "manual" | "off";

export type KnowledgeSpecialistRole = (readonly [
	{
		readonly role: "navigator";
		readonly name: "knowledge-navigator";
		readonly label: "知识导航员";
		readonly description: "按导航检索共享知识与当前项目，只返回少量相关来源。";
		readonly permissions: readonly ["knowledge_read", "knowledge_search", "knowledge_submit"];
		readonly maxTurns: 6;
		readonly maxTokens: 1800;
	},
	{
		readonly role: "evidence";
		readonly name: "knowledge-evidence-curator";
		readonly label: "证据整理员";
		readonly description: "核对指定来源的适用范围、冲突与缺口，不自动认证结论。";
		readonly permissions: readonly ["knowledge_read", "knowledge_submit"];
		readonly maxTurns: 4;
		readonly maxTokens: 2400;
	},
	{
		readonly role: "wiki";
		readonly name: "knowledge-wiki-editor";
		readonly label: "Wiki 修订员";
		readonly description: "根据已读证据生成待审核修订正文，无正式 Wiki 写入与批准权限。";
		readonly permissions: readonly ["knowledge_read", "knowledge_submit"];
		readonly maxTurns: 3;
		readonly maxTokens: 6500;
	},
	{
		readonly role: "explainer";
		readonly name: "knowledge-explainer";
		readonly label: "Show Me 讲解员";
		readonly description: "按实际 Show Me skill 生成独立讲解产物，由宿主保存；不执行软件或测试。";
		readonly permissions: readonly ["knowledge_read", "knowledge_submit"];
		readonly maxTurns: 3;
		readonly maxTokens: 12000;
	},
	{
		readonly role: "reviewer";
		readonly name: "knowledge-wiki-reviewer";
		readonly label: "Wiki 模型审核员";
		readonly description: "独立核对选中的候选和来源，仅返回审核意见；自动应用须由用户单独授权。";
		readonly permissions: readonly ["knowledge_submit"];
		readonly maxTurns: 1;
		readonly maxTokens: 2800;
	},
])[number]["role"];

