	stage: string | null;
	contract: string | null;
	primary: string | null;
	reason: string | null;
	unavailableStage: string | null;
	comparison: boolean;
	academic: boolean;
	keptCheckpoint: boolean;
	deferPhrase: boolean;
	visiblePrimary: boolean;
